catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) return;

    g_form.clearValue('schedule');

    var ga = new GlideAjax('TrainingHubUtils');
    ga.addParam('sysparm_name', 'getValidSchedules');
    ga.addParam('sysparm_course_id', newValue);
    ga.getXMLAnswer(function(response) {
        g_form.setFieldPlaceholder('schedule', 'Select a schedule');
    });
}
